import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction, limit } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = '${req.tenantId}'`;

    // Apply filters
    if (category) {
      query += ` AND category = '${category}'`;
    }
    if (status) {
      query += ` AND status = '${status}'`;
    }

    // Dynamic ordering
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    if (sort_by && allowedSorts.includes(sort_by)) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Limit results
    const resultLimit = parseInt(limit) || 50;
    query += ` LIMIT ${Math.min(resultLimit, 200)}`;

    const result = await pool.query(query);

    // Audit log (async, non-blocking)
    const auditHash = crypto.createHash('sha256')
      .update(`${req.tenantId}:${Date.now()}:search`)
      .digest('hex');
    pool.query(
      'INSERT INTO audit_log (hash, tenant_id, action, query_text) VALUES ($1, $2, $3, $4)',
      [auditHash, req.tenantId, 'asset_search', query]
    ).catch(() => {});

    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, new_status, note } = req.body;

  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids must be non-empty array' });
  }
  if (asset_ids.length > 100) {
    return res.status(400).json({ error: 'Maximum 100 assets per batch' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Note: relies on tenant_id in WHERE for isolation
    const idList = asset_ids.map(id => `'${id}'`).join(',');
    const updateQuery = `UPDATE assets SET status = '${new_status}', 
      updated_at = NOW(), 
      notes = '${(note || '').replace(/'/g, "''")}'
      WHERE tenant_id = '${req.tenantId}' AND id IN (${idList})`;

    const result = await client.query(updateQuery);
    await client.query('COMMIT');

    res.json({ updated: result.rowCount });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Asset service running on :3000'));
